{"implementation": "def solve(case):
    # Validate required fields
    for field in ("nodes", "core_distance", "distances"):
        if field not in case:
            raise ValueError(f"Missing required field: {field}")

    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    if not isinstance(nodes, list) or len(nodes) == 0:
        raise ValueError("'nodes' must be a non-empty list")

    n = len(nodes)

    for node in nodes:
        if node not in core_distance:
            raise ValueError(f"Node '{node}' missing from core_distance")

    # Compute mutual reachability for each edge
    mr_edges = []
    for entry in distances:
        if len(entry) != 3:
            raise ValueError(f"Distance entry must have 3 elements: {entry}")
        a, b, d = entry[0], entry[1], entry[2]

        if a not in core_distance:
            raise ValueError(f"Node '{a}' in distances not found in core_distance")
        if b not in core_distance:
            raise ValueError(f"Node '{b}' in distances not found in core_distance")

        # Canonicalize undirected endpoints
        u, v = (a, b) if a <= b else (b, a)

        mr = max(core_distance[a], core_distance[b], d)
        mr_edges.append((u, v, mr))

    # Sort by mutual reachability weight, then by canonicalized endpoint IDs
    mr_edges.sort(key=lambda e: (e[2], e[0], e[1]))

    # Kruskal's algorithm with union-find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        # Path compression
        while parent[x] != root:
            nxt = parent[x]
            parent[x] = root
            x = nxt
        return root

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        # Union by rank; tie-break by node ID for determinism
        if rank[rx] < rank[ry] or (rank[rx] == rank[ry] and rx > ry):
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    selected = []
    total_weight = 0.0

    for u, v, mr in mr_edges:
        if union(u, v):
            selected.append({"u": u, "v": v, "weight": mr})
            total_weight += mr
            if len(selected) == n - 1:
                break

    if len(selected) != n - 1:
        raise ValueError("Input graph is disconnected; MST cannot be formed")

    return {
        "mst_edges": selected,
        "total_weight": total_weight
    }
